module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg         clk;
    reg         resetn;
    reg   [1:0] byteena;
    reg  [15:0] d;
    wire [15:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .resetn(resetn),
        .byteena(byteena),
        .d(d),
        .q(q)
    );

    // Clock generation
    always #5 clk = ~clk;

    integer errors = 0;
    reg [15:0] expected_q;

    // Task to check outputs
    task check_output(input [15:0] exp);
        begin
            #1; // Small delay to sample after positive edge
            if (q !== exp) begin
                $display("Time %0t: Mismatch! d=%h, byteena=%b, q=%h, expected=%h", 
                         $time, d, byteena, q, exp);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        resetn = 0;
        byteena = 2'b00;
        d = 16'h0000;
        expected_q = 16'h0000;

        // Apply reset
        #12;
        check_output(16'h0000);

        // Release reset
        resetn = 1;
        @(posedge clk);

        // Test 1: Write nothing (byteena = 00)
        d = 16'hABCD;
        byteena = 2'b00;
        @(posedge clk);
        check_output(16'h0000);

        // Test 2: Write lower byte only (byteena = 01)
        d = 16'h1234;
        byteena = 2'b01;
        expected_q[7:0] = 16'h34;
        expected_q[15:8] = 16'h00;
        @(posedge clk);
        check_output(expected_q);

        // Test 3: Write upper byte only (byteena = 10)
        d = 16'h5678;
        byteena = 2'b10;
        expected_q[15:8] = 16'h56;
        // lower byte should remain unchanged (0x34)
        @(posedge clk);
        check_output(expected_q);

        // Test 4: Write both bytes (byteena = 11)
        d = 16'hCAFE;
        byteena = 2'b11;
        expected_q = 16'hCAFE;
        @(posedge clk);
        check_output(expected_q);

        // Test 5: Synchronous active-low reset
        @(posedge clk);
        resetn = 0;
        byteena = 2'b11;
        d = 16'hFFFF;
        expected_q = 16'h0000;
        @(posedge clk);
        check_output(expected_q);

        // Final status report
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
